create or replace function private.is_agent_manager(org bigint, member uuid) returns boolean language sql stable security definer set search_path='' as $$ select public.get_user_role(org)='owner' or exists(select 1 from public.team_members s join public.team_members boss on boss.organization_id=org where s.id=member and s.organization_id=org and boss.user_id=(select auth.uid()) and boss.status='active' and private.can_area(org,'people',null,true) and (boss.id=s.reports_to_member_id or (s.kind='human' and s.reports_to_member_id is null and s.user_id is not null and boss.kind='agent' and boss.reports_to_member_id is null))); $$; revoke all on function private.is_agent_manager(bigint,uuid) from public; grant execute on function private.is_agent_manager(bigint,uuid) to authenticated; comment on function private.is_agent_manager(bigint,uuid) is 'Direct supervisors review their team. The root operations agent reviews root human operational reports. Self-review remains denied by reviews_insert and the API; ownership and platform permissions are unchanged.';
